function LeadHistoryDialog({ lead, calls, onClose }: { lead: Lead; calls: CallRecord[]; onClose: () => void }) {
  const details=leadCustomData(lead); const detailRows=[["الاسم",lead.fullName],["موبايل 1",lead.primaryPhone],["موبايل 2",lead.secondaryPhone||"—"],["النوع",String(details.gender||"—")],["العمر",String(details.age||"—")],["الموقع",String(details.location||"—")],["الفرع",lead.branchName||"—"],["الكورس",lead.interest||"—"],["الشريحة",String(details.segment||"—")],["الوظيفة",String(details.job||"—")],["العرض",String(details.offer||"—")]];
  return <div className="overlay" onMouseDown={(e)=>e.target===e.currentTarget&&onClose()}><section className="dialog history-dialog"><div className="dialog-head"><div><span className="dialog-icon">◉</span><div><h2>سجل العميل [{lead.primaryPhone}]</h2><p>البيانات الكاملة وكل المكالمات المسجلة</p></div></div><button onClick={onClose}>×</button></div><div className="history-summary">{detailRows.map(([label,value])=><div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><div className="history-section"><h3>سجل المكالمات</h3>{calls.length?<div className="table-wrap"><table><thead><tr><th>النتيجة</th><th>المرحلة</th><th>وقت الإجراء</th><th>الملاحظات</th><th>الموظف</th></tr></thead><tbody>{calls.map((call)=><tr key={call.id}><td><CallResult value={call.result}/></td><td>Lead</td><td>{formatDate(call.callAt)}</td><td className="notes-cell">{call.notes||"—"}</td><td>{call.assignedEmployee||"—"}</td></tr>)}</tbody></table></div>:<div className="empty-history">لا توجد مكالمات مسجلة لهذا العميل.</div>}</div><div className="dialog-foot"><button className="secondary" onClick={onClose}>إغلاق</button></div></section></div>;
}

function Metric({ label, value, hint, tone }: { label: string; value: number; hint: string; tone: string }) { return <article className="metric"><span className={`metric-icon ${tone}`}>◆</span><div><small>{label}</small><strong>{String(value).padStart(2,"0")}</strong><p>{hint}</p></div></article>; }
function Status({ status }: { status: Employee["status"] }) { const map = { active:"نشط", invited:"دعوة معلقة", disabled:"موقوف" }; return <span className={`status ${status}`}><i />{map[status]}</span>; }
function initials(name: string) { return name.split(" ").slice(0,2).map((part) => part[0]).join(""); }
function parseOptions(field: Field) { try { return JSON.parse(field.optionsJson || "[]") as string[]; } catch { return []; } }

function EmployeeDialog({ data, onClose, onSubmit }: { data: Setup; onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  const [values, setValues] = useState<Record<string, unknown>>({ startDate: new Date().toISOString().slice(0,10) }); const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const fields=data.fields.filter((f)=>f.visible);
  async function submit(e: FormEvent){e.preventDefault();setBusy(true);setError("");try{const standard=new Set(["fullName","email","phone","departmentId","jobTitleId","roleId","branchId","status"]);const customData=Object.fromEntries(Object.entries(values).filter(([k])=>!standard.has(k)));await onSubmit({...values,customData});}catch(err){setError(err instanceof Error?err.message:"تعذر الحفظ");setBusy(false)}}
  return <div className="overlay" onMouseDown={(e)=>e.target===e.currentTarget&&onClose()}><form className="dialog employee-dialog" onSubmit={submit}><div className="dialog-head"><div><span className="dialog-icon">＋</span><div><h2>إضافة موظف جديد</h2><p>بيانات الملف الوظيفي وحساب الدخول.</p></div></div><button type="button" onClick={onClose}>×</button></div>{error&&<p className="form-error">{error}</p>}<div className="employee-form-note"><span>▤</span><p>هذا النموذج ديناميكي. يمكنك إخفاء أي حقل أو إضافة حقول جديدة من «مصمم النماذج».</p></div><div className="dynamic-grid dialog-fields">{fields.map((f)=><DynamicField key={f.id} field={f} value={values[f.fieldKey]} setValue={(v)=>setValues((current)=>({...current,[f.fieldKey]:v}))} data={data} values={values}/>)}</div><div className="dialog-foot"><button className="secondary" type="button" onClick={onClose}>إلغاء</button><button className="primary" disabled={busy}>{busy?"جارٍ الحفظ...":"إنشاء ملف الموظف"}</button></div></form></div>;
}

function DynamicField({ field, value, setValue, data, values, disabled=false }: { field: Field; value: unknown; setValue:(v:unknown)=>void; data:Setup; values:Record<string,unknown>; disabled?:boolean }) {
  let options:{id:string|number;name:string}[]=parseOptions(field).map((name)=>({id:name,name}));
  if(field.fieldKey==="departmentId") options=data.departments.map((d)=>({id:d.id,name:d.name}));
  if(field.fieldKey==="jobTitleId") options=data.jobTitles.filter((j)=>!values.departmentId||j.departmentId===Number(values.departmentId)).map((j)=>({id:j.id,name:j.name}));
  if(field.fieldKey==="roleId") options=data.roles.map((r)=>({id:r.id,name:r.name}));
  if(field.fieldKey==="assignedEmployeeId") options=data.employees.filter((employee)=>employee.status==="active").map((employee)=>({id:employee.id,name:employee.fullName}));
  if(field.fieldKey==="branchId") options=data.branches.filter((branch)=>branch.isActive||Number(value)===branch.id).map((branch)=>({id:branch.id,name:branch.name}));
  const common={disabled,required:!!field.required};
  if(field.type==="textarea") return <label className="full"><span>{field.label}{field.required?" *":""}</span><textarea value={String(value??"")} placeholder={field.placeholder} onChange={(e)=>setValue(e.target.value)} disabled={disabled} required={!!field.required}/></label>;
  if(field.type==="checkbox") { const selected=Array.isArray(value)?value as string[]:[]; return <fieldset className="full document-field"><legend>{field.label}</legend><div>{options.map((o)=><label key={o.id}><input type="checkbox" checked={selected.includes(String(o.id))} disabled={disabled} onChange={(e)=>setValue(e.target.checked?[...selected,String(o.id)]:selected.filter((x)=>x!==String(o.id)))} /><span>✓</span>{o.name}</label>)}</div></fieldset>; }
  return <label className={field.width==="full"?"full":""}><span>{field.label}{field.required?" *":""}</span>{field.type==="select"?<select value={String(value??"")} onChange={(e)=>setValue(e.target.value)} {...common}><option value="">{field.placeholder}</option>{options.map((o)=><option key={o.id} value={o.id}>{o.name}</option>)}</select>:<input value={String(value??"")} onChange={(e)=>setValue(e.target.value)} placeholder={field.placeholder} type={field.type} {...common}/>}</label>;
}
function BaseDialog({ title, subtitle, icon, onClose, onSubmit, children, busyText="جارٍ الحفظ...", submitText="حفظ" }: { title:string;subtitle:string;icon:string;onClose:()=>void;onSubmit:(e:FormEvent<HTMLFormElement>)=>void;children:React.ReactNode;busyText?:string;submitText?:string }) { const [busy,setBusy]=useState(false); return <div className="overlay" onMouseDown={(e)=>e.target===e.currentTarget&&onClose()}><form className="dialog compact" onSubmit={(e)=>{setBusy(true);onSubmit(e)}}><div className="dialog-head"><div><span className="dialog-icon">{icon}</span><div><h2>{title}</h2><p>{subtitle}</p></div></div><button type="button" onClick={onClose}>×</button></div><div className="dynamic-grid dialog-fields">{children}</div><div className="dialog-foot"><button className="secondary" type="button" onClick={onClose}>إلغاء</button><button className="primary" disabled={busy}>{busy?busyText:submitText}</button></div></form></div>; }

function DepartmentDialog({departments,onClose,onSubmit}:{departments:Department[];onClose:()=>void;onSubmit:(p:Record<string,unknown>)=>Promise<void>}) { return <BaseDialog title="إضافة قسم" subtitle="سيظهر مباشرة داخل نموذج الموظف" icon="≡" onClose={onClose} submitText="إضافة القسم" onSubmit={async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);await onSubmit({name:f.get("name"),parentId:f.get("parentId"),color:f.get("color"),supportEnabled:f.get("supportEnabled")==="on"})}}><label className="full"><span>اسم القسم *</span><input name="name" required placeholder="مثال: التسويق" /></label><label><span>القسم الرئيسي</span><select name="parentId"><option value="">بدون قسم رئيسي</option>{departments.map((d)=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label><label><span>لون القسم</span><input name="color" type="color" defaultValue="#2f6b5f" /></label><label className="inline-check full"><input type="checkbox" name="supportEnabled" /> تفعيل خيارات الدعم لهذا القسم</label></BaseDialog>; }
