function JobDialog({departments,onClose,onSubmit}:{departments:Department[];onClose:()=>void;onSubmit:(p:Record<string,unknown>)=>Promise<void>}) { return <BaseDialog title="إضافة دور وظيفي" subtitle="اختر القسم الذي تتبعه الوظيفة" icon="◆" onClose={onClose} submitText="إضافة الوظيفة" onSubmit={async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);await onSubmit({name:f.get("name"),departmentId:f.get("departmentId")})}}><label className="full"><span>اسم الوظيفة *</span><input name="name" required placeholder="مثال: مسؤول مبيعات" /></label><label className="full"><span>القسم *</span><select name="departmentId" required><option value="">اختر القسم</option>{departments.map((d)=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label></BaseDialog>; }
